"""Read-only Case021 public-aggregate display; no scientific GPU source imports."""
from html import escape
import importlib.util
from common import read,sha,require
C21='cases/021-rounding-execution-diagnostics'
TITLES={'ko':'같은 INT4인데 왜 계산 결과가 달라질까?','en':'Why can the same INT4 artifact produce different results?'}
SECTIONS=('overview','comparisons','rounding','single-term','sparse','reproduce','sources')
SOURCE_COPIES={
 **{'case021-'+kind+'-'+lang+'.md.txt':C21+'/'+name+('.ko.md' if lang=='ko' else '.md') for kind,name in [('guide','README'),('report','REPORT'),('reproduce','REPRODUCE'),('method','METHOD_CONTRACT')] for lang in ('ko','en')},
 **{'case021-'+kind+'.md.txt':C21+'/'+name+'.md' for kind,name in [('notice','NOTICE'),('sources','SOURCE_MAP'),('reuse','REUSE_MAP'),('history','HISTORY')]},
 'case021-facts.json.txt':C21+'/summary/facts.json','case021-derive.py.txt':C21+'/publication/derive.py','case021-checks.py.txt':C21+'/publication/run_checks.py','case021-requirements.txt':C21+'/publication/requirements-cpu.txt',
 'case021-primary.csv.txt':C21+'/evidence/p0p3/primary.csv','case021-cross.csv.txt':C21+'/evidence/p4/cross_precision_document.csv',
 'case021-gap.csv.txt':C21+'/history/p5/summary/local_gap_components.csv','case021-candidate.csv.txt':C21+'/history/p5/summary/candidate_fit.csv','case021-sparse.csv.txt':C21+'/history/p5/summary/sparse_metrics.csv'}
FIGURES={'assets/case021-'+n+'.svg':C21+'/figures/'+n+'.svg' for n in ['01_overview','02_cross_precision']}
def module(path,name):
 spec=importlib.util.spec_from_file_location(name,path);m=importlib.util.module_from_spec(spec);spec.loader.exec_module(m);return m
def load_case021(root):
 case=root/C21
 if not (case/'README.md').exists():return None
 identity=module(case/'publication/verify.py','c21_identity').verify(case)
 f=module(case/'publication/derive.py','c21_derive').projection(case)
 require(f==read(case/'summary/facts.json'),'Case021 aggregate/source facts mismatch')
 sources=[*SOURCE_COPIES.values(),*FIGURES.values(),C21+'/PUBLIC_MANIFEST.json']
 return {'facts':f,'public_identity':{'manifest_sha256':sha(case/'PUBLIC_MANIFEST.json'),'files':identity['public_files'],'bytes':identity['public_bytes']},'display_source_files':{p:sha(root/p) for p in sources}}
def link(url,label):return '<a href="'+escape(url,quote=True)+'">'+escape(label)+'</a>'
def table(head,rows,label):return '<div class="scroll" tabindex="0" role="region" aria-label="'+escape(label,quote=True)+'"><table><thead><tr>'+''.join('<th scope="col">'+escape(x)+'</th>' for x in head)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+escape(str(x))+'</td>' for x in row)+'</tr>' for row in rows)+'</tbody></table></div>'
def home_case021(data,lang):
 f=data['facts'];t=lambda k,e:k if lang=='ko' else e
 return '<section class="panel" id="case021-entry"><h2>Case021 · '+escape(TITLES[lang])+'</h2><p>'+t('같은 압축 숫자를 사용하는 dense/Marlin을 비교했습니다. 검사한 단일항은 같았지만 실제 activation 값을 결합하면 작은 차이가 남았습니다.','Dense and Marlin used the same compressed numbers. Tested single terms matched, but combining actual activation values left small differences.')+'</p><p>'+t('Q/K 중간 정밀도를 높였을 때 평균 KL 감소 여부는 ','Higher Q/K intermediate precision left the mean KL reduction verdict ')+f['original_primary_verdict']+t('입니다. 분포의 가까움과 모델 정답률은 다른 지표입니다.','; distribution agreement is not task accuracy.')+'</p><div class="actions">'+link('case021.html#overview',t('쉽게 읽기','Plain explanation'))+' · '+link('case021.html#sparse',t('실제 값의 결합','Combining actual values'))+' · '+link('case021.html#reproduce',t('CPU 검산','CPU checks'))+'</div></section>'
def render_case021(data,lang):
 f=data['facts'];ko=lang=='ko';t=lambda k,e:k if ko else e
 labels=dict(zip(SECTIONS,[t('질문과 비교','Question and comparison'),t('원 결과와 교차 비교','Original and cross comparison'),t('오차의 상쇄','Error cancellation'),t('값 하나를 곱할 때','One nonzero product'),t('실제 값을 결합할 때','Combining actual values'),t('공개 CPU 검산','Public CPU checks'),t('방법·출처·이력','Methods, sources and history')]))
 out='<article><nav aria-label="'+t('이 문서에서','On this page')+'">'+' · '.join(link('#'+s,labels[s]) for s in SECTIONS)+'</nav>'
 def section(s,b):return '<section class="panel" id="'+s+'"><h2>'+labels[s]+'</h2>'+b+'</section>'
 def fig(n,alt,caption):return '<figure><img loading="lazy" src="../assets/case021-'+n+'.svg" alt="'+escape(alt,quote=True)+'"><figcaption>'+escape(caption)+'</figcaption></figure>'
 intro='<h1>'+escape(TITLES[lang])+'</h1><p>'+t('같은 압축 숫자를 사용해도 반올림 시점과 계산 경로에 따라 마지막 값이 달라질 수 있습니다. Qwen3-0.6B의 저장 표현, dense/Marlin 실행, 그 뒤 Q/K 계산 정밀도를 나누어 조사했습니다.','The same compressed numbers can lead to different final values when rounding boundaries and execution paths differ. The Qwen3-0.6B study separates representation, dense/Marlin execution and later Q/K precision.')+'</p>'
 intro+=table(['Path',t('하는 일','Meaning')],[['D0',t('기존 순서로 복원한 dense 참조','Dense reference reconstructed in the original order')],['D1',t('BF16 scale과 가중치를 미리 복원한 일반 행렬곱','General matrix multiplication with BF16 scales and preconstructed BF16 weights')],['P',t('같은 code/scale을 Marlin 압축 실행에 전달','The same codes/scales supplied to packed Marlin')],['R0/R1',t('공통 Q/K norm–RoPE의 기본 중간값 /FP32 중간값 후 BF16 출력','Native Q/K norm–RoPE /FP32 intermediates then BF16 outputs')]],'D0 D1 P R0 R1')
 intro+='<p>'+t('artifact는 다시 실행할 code·scale의 묶음, INT4는 weight code를4비트로 저장하는 형식입니다. D16은 기존 W4A16 설정명이며16비트 weight가 아닙니다. dense는 가중치를 먼저 복원하는 경로, activation은 다음 계산에 전달되는 값입니다.','An artifact stores codes/scales for replay; INT4 stores weight codes in4 bits. D16 is the existing W4A16 setting name, not16-bit weights. Dense reconstructs weights first; activations are values passed to the next calculation.')+'</p>'
 intro+='<ul><li>'+t('단일항: A/B를 구분한 ', 'Single terms: ')+f"{f['single_term']['discriminating_coordinates']:,}"+t('기록 좌표에서도 D1/P가 같고 후보 A와 맞았습니다.',' recorded coordinates distinguished A/B, yet D1/P matched candidate A.')+'</li><li>'+t('실제 값 결합: 두 층×두 DEV 문서의 고정 grid에서 K8 또는64부터 작은 차이가 보였습니다.','Actual-value combinations: small differences first appeared at K8 or64 in the fixed grid of two layers × two DEV documents.')+'</li><li>'+t('전체 분포: 원24문서의 중간 정밀도 효과는 ','Full distributions: the original24-document precision-effect verdict remains ')+f['original_primary_verdict']+'.</li></ul>'
 intro+=fig('01_overview','Sparse D1/P mismatch and original document KL',t('왼쪽 점은4개 고정 입력의 조건, 오른쪽 선은 원24문서입니다. K축은 log2이고0 차이도 남겼습니다.','Left points are fixed-input conditions; right lines are24 original documents. K uses log2 and zero differences remain.'));out+=section('overview',intro)
 cross=next(x for x in f['cross'] if x['split']=='original_EVAL_posthoc' and x['length']==512)
 body=table(['EVAL512 /24 documents','KL (nats)'],[['E0',f"{f['E0']:.13f}"],['E1',f"{f['E1']:.13f}"],['delta E0−E1',f"{f['delta']:.13f}"],['paired95% /seed'+str(f['primary_seed']),f"[{f['original_ci'][0]:.13f}, {f['original_ci'][1]:.13f}]"],['verdict',f['original_primary_verdict']]],'Original primary result')
 body+='<p>'+t('KL/JSD는 다음 토큰 후보 분포의 차이이고 낮을수록 가깝습니다. 정답률이 아닙니다. 각 문서의16위치 평균 뒤 문서에 같은 가중치를 줍니다. 원 delta 구간이0을 포함하므로 감소를 확정하지 못했습니다.','KL/JSD measure next-token distribution differences; lower is closer, not more correct. Each document averages16 positions before equal document weighting. The original delta interval crosses zero, leaving reduction unresolved.')+'</p>'
 body+=table(['Fixed reference','P_R0 KL','P_R1 KL'],[[r,f"{cross['K'+str(i)+'0']:.10f}",f"{cross['K'+str(i)+'1']:.10f}"] for i,r in enumerate(['D1_R0','D1_R1'])],'Posthoc cross precision KL')
 body+='<p>'+t('행 안에서 D1_R0를 고정하면 P_R1이 멀어지고 D1_R1을 고정하면 가까워졌습니다. 참조까지 바꾼 대각 비교는 한쪽만 바꾼 효과가 아닙니다. 기존 EVAL의 사후 분석이며 원 주 판정을 대체하지 않습니다.','Within a fixed-reference row, P_R1 moves farther from D1_R0 but closer to D1_R1. Changing both endpoints is not a one-sided effect. This is post-hoc reanalysis of existing EVAL, not a new confirmation or replacement verdict.')+'</p>'+fig('02_cross_precision','KL and JSD two by two',t('같은 행 안에서 비교합니다. 원 주 구간과 사후 bootstrap seed는 다릅니다.','Compare within a row. Original and post-hoc bootstrap seeds remain distinct.'));out+=section('comparisons',body)
 rows=[]
 for key,label in [('DN_NONPOS_DC_POS','ΔN≤−tol, ΔC>tol'),('DN_POS_DC_POS','ΔN>tol, ΔC>tol'),('DN_POS_DC_NONPOS','ΔN>tol, ΔC≤−tol')]:rows.append([label,f['gap_classes'][key],f['weaker_negative_cross_by_class'].get(key,0)])
 body='<p>'+t('국소 FP64 식에서 입력 차이가 만드는 값 d와 두 계산 오차의 차이 n을 나눴습니다. G=||d||²+N+C, N=||n||², C=2〈d,n〉입니다. 같은 좌표의 R0→R1 변화는 ΔG=ΔN+ΔC입니다.','The local FP64 formula separates the difference d induced by projection inputs from the difference n in calculation errors. G=||d||²+N+C, N=||n||², C=2〈d,n〉. At the same coordinates, the R0→R1 change is ΔG=ΔN+ΔC.')+'</p>'+table([t('gap 증가 분류','Gap-increase class'),t('수','Count'),t('음의 cross 약화','Weaker negative cross')],rows,'Local energy change')
 body+='<p>'+t('96은24문서×2층×Q/K입니다. 개별 참조 오차 합은 모두 줄었지만 gap은34증가/57감소/5동일입니다. 위30개의 ΔC 증가를 모두 음의 상쇄 소멸로 읽지 않습니다. 해당 패턴은24개입니다. 이 국소 항등식은 전체 KL의 인과 기여율이 아닙니다.','96 means24 documents ×2 layers ×Q/K. Individual reference-error sums all fell, but gaps increased34/decreased57/tied5. The30 positive ΔC cases are not all lost negative cancellation; that pattern covers24. This local identity is not a causal contribution to full-model KL.')+'</p>';out+=section('rounding',body)
 body='<p>A=R_BF16(a×R_BF16(c×s)); B=R_BF16(a×c×s).</p><p>'+t('A는 가중치를 먼저 반올림하고, B는 곱의 끝에서 반올림합니다. c는 INT4 code, s는 BF16 scale, a는 beta 적용 후 BF16 입력입니다. 설명용 합성 c=3,s=1.0078125에서 a=1이면 둘 다3.03125, a=1.5이면 A4.5625/B4.53125입니다. 실제 artifact에 이 숫자가 있다는 뜻은 아닙니다.','A rounds the weight first; B rounds at the end of the product. c is an INT4 code, s a BF16 scale, a the post-beta BF16 input. In the synthetic illustration c=3,s=1.0078125, a=1 gives3.03125 for both; a=1.5 gives A4.5625/B4.53125. These are not claimed to be actual artifact values.')+'</p>'
 body+=table(['First-block scope','Coordinates'],[[k,f"{f['single_term'][k]:,}"] for k in ['coordinates','A_only','both','B_only','neither']],'Single-term candidate fit')
 body+='<p>'+t('406,626은 fixture/행/출력 좌표의 첫 block 기록 수입니다. 입력 행5,120회 중 고유 layer/axis/coefficient는4,102개로1,018회가 재사용됐습니다. process3반복이나 중복 제거한 수학적 쌍을 센 값이 아닙니다. both는 판별 증거가 아니며, A와의 일치는 검사한 단일항에서 A와 양립한다는 뜻입니다. kernel 전체 내부 순서를 증명하지 않습니다.','406,626 counts first-block fixture/row/output-coordinate records. The5,120 input-row occurrences contain4,102 distinct layer/axis/coefficient triples and1,018 reuses. This is neither a3-process multiplier nor deduplicated mathematical pairs. Both is non-discriminating. Matching A supports A-compatible behavior on tested single terms, not every internal kernel ordering.')+'</p>';out+=section('single-term',body)
 body=table(['Layer/document','First K','K1024 relative_RMSE','Mismatch %','Max BF16 steps'],[[str(r['layer'])+'/'+r['document_id'],r['first_observed_K'],f"{r['K1024_relative_RMSE']:.8f}",f"{100*r['K1024_mismatch_fraction']:.4f}",r['K1024_max_steps']] for r in f['sparse']],'Four actual input combinations')
 body+='<p>'+t('고정 K={1,2,8,64,256,1024} 중 K1/2는 모두 같았습니다. K1024 입력과 D1/P 출력은 과거 P4와 bit 대응합니다. 각512행×2048출력 좌표를3process에서 확인했으며 독립 workload12개가 아닙니다. 남긴 값·norm·상쇄 구조가 함께 변하므로 K8/64를 보편적 임계값이나 순수 누적 순서의 증거로 쓰지 않습니다. ULP는 인접 BF16 표현 단계이며 내부 반올림 횟수가 아닙니다.','K1/2 matched for all four combinations in the fixed grid K={1,2,8,64,256,1024}. K1024 inputs and D1/P outputs match historical P4 bits. Each512-row ×2048-output condition was checked in3 processes, not12 independent workloads. Values, norm and cancellation change together, so K8/64 are not universal thresholds or proof of pure accumulation order. ULP counts representable BF16 steps, not internal rounding operations.')+'</p>';out+=section('sparse',body)
 cmd='python3.11 -m venv /tmp/case021-cpu\n/tmp/case021-cpu/bin/python -m pip install -r '+C21+'/publication/requirements-cpu.txt\nCUDA_VISIBLE_DEVICES= HF_HUB_OFFLINE=1 OPENBLAS_NUM_THREADS=1 /tmp/case021-cpu/bin/python -I -B '+C21+'/publication/run_checks.py --mode full --tests --output /tmp/case021-full-new'
 body='<p>'+t('Git checkout의 집계 CSV와 합성 fixture만으로 검산합니다. Python3.11.15/NumPy1.26.4/Matplotlib3.10.9, Linux/WSL에서 확인하는 경로입니다. quick은 해시·분모·통계·합성 산술, full은 그림 재생성을 더합니다. private logits에서 KL을 다시 계산하거나 GPU 실험을 재실행하는 검사가 아닙니다.','Checks use only Git-checkout aggregate CSVs and synthetic fixtures. The path uses Python3.11.15/NumPy1.26.4/Matplotlib3.10.9 on Linux/WSL. Quick checks hashes, denominators, statistics and synthetic arithmetic; full adds figures. Neither recomputes KL from private logits nor reruns GPU experiments.')+'</p><pre><code>'+escape(cmd)+'</code></pre><p>'+link('../sources/case021-reproduce-'+lang+'.md.txt',t('실제 범위와 명령','Commands and scope'))+' · '+link('../sources/case021-checks.py.txt','CPU wrapper')+' · '+link('../sources/case021-derive.py.txt',t('집계 코드','Derivation'))+'</p>';out+=section('reproduce',body)
 body='<p>'+t('직접 만든 것은 adapter·fixture·계측·독립 산술 검산·집계·표시 도구입니다. Qwen/HF 모형과 Torch/Marlin 연산을 재사용했고 Codex가 구현·분석·문서를 보조했습니다. 과거2% gate 미통과와 실패·수정·driver drift는 이력에 보존했습니다. 새 GPU0이며 이 화면의 빌드는 Pages 배포와 별개입니다.','Direct work covers adapters, fixtures, measurement, independent arithmetic checks, aggregation and display. Qwen/HF and Torch/Marlin operations are reused; Codex assisted implementation, analysis and documentation. Historical2% failure, corrections and driver drift remain in the history. New GPU runs:0; building this page is separate from Pages deployment.')+'</p><p>'+link('../sources/case021-method-'+lang+'.md.txt',t('방법 계약','Method contract'))+' · '+link('../sources/case021-report-'+lang+'.md.txt',t('상세 보고서','Report'))+' · '+link('../sources/case021-history.md.txt',t('실행 이력','Execution history'))+' · '+link('../sources/case021-sources.md.txt',t('출처','Source map'))+' · '+link('https://arxiv.org/abs/2610.32951v1','Paper v1')+' · '+link('https://github.com/Munsik-Kim/inference-lab/tree/main/'+C21,'GitHub Case021')+'</p>';out+=section('sources',body)
 return out+'<noscript><p>'+t('표·그림·원자료 링크는 JavaScript 없이 읽을 수 있습니다.','Tables, figures and source links work without JavaScript.')+'</p></noscript></article>'
